function showErrorMessage(n,t){t.html(" <strong>خطا!<\/strong> "+n);t.removeClass("hide");t.removeClass("fade");t.addClass("show")}function showSuccessfulMessage(n,t){t.html(n);t.removeClass("hide");t.removeClass("fade");t.addClass("show")}function hideErrorMessage(n){n.html("");n.removeClass("show");n.addClass("hide");n.addClass("fade")}function disableButtonAndShowSnipper(n,t=true){var n=$("#"+n),i,r;disableButton(n);t&&(i=n.find(".fa-spin"),i&&i.length>0?showSpinner(i):(r=$('<i id="spinner" class="fas fa-spinner fa-spin"><\/i>'),n.append(r)))}function enableButtonAndHideSnipper(n){var n=$("#"+n),t;enableButton(n);t=n.find(".fa-spin");t&&hideSpinner(t)}function showSpinner(n){n.css("visibility","visible");n.css("display","")}function hideSpinner(n){n.css("display","none")}function disableButton(n){n.prop("disabled",!0)}function enableButton(n){n.prop("disabled",!1)}